// Writes docs/constants.md from packages/shared/src/constants/: one section per exported group, in
// the barrel's order, with each value's source text and doc comment. `--check` writes nothing and
// exits 1 when the file on disk differs (CI). Run with `pnpm constants:docs [--check]`.
import { readFileSync, writeFileSync } from 'node:fs';
import ts from 'typescript';

const SOURCE_DIR = new URL('../src/constants/', import.meta.url);
const OUTPUT = new URL('../../../docs/constants.md', import.meta.url);

const HEADER = `# Constants

<!-- Generated by \`pnpm constants:docs\` from packages/shared/src/constants/. Edit the source files, not this one; CI fails when it is stale. -->

Tunable values live in \`packages/shared/src/constants/\`, one file per domain, re-exported by \`@cgis/shared\` (and by \`@cgis/shared/constants\` for Node-side config files such as \`vite.config.ts\`). App code imports them instead of writing literals. Each section below is one exported group; the notes are the doc comments in the source.

Visual design tokens (spacing, type, colour ramps and semantic colours, map styles, radii, z-index, motion) live in one CSS file, [\`apps/web/src/styles/tokens.css\`](../apps/web/src/styles/tokens.css) (design system "Grid 4", D15–D18). The map pane z-indexes are defined here and mirrored there; \`apps/web/src/styles/tokens.test.ts\` fails when they drift. Presence hues are \`MAP.PRESENCE_COLORS\` only: the server hashes each user id into that palette and sends the colour, and the web applies it per element. The draw tool splits by who needs the value: Leaflet's numbers (\`MAP.HANDLE_HIT_PX\`, \`MAP.DRAFT_STYLE\`) live here; the handle dot and the sketch colours are CSS.
`;

type Row = { name: string; value: string; note: string };
type Section = { title: string; intro: string; rows: Row[] };

/** The text of the last `/** … *\/` comment before `node`, on one line; '' without one. */
function docOf(node: ts.Node, text: string): string {
  const ranges = ts.getLeadingCommentRanges(text, node.getFullStart()) ?? [];
  const doc = ranges
    .map((range) => text.slice(range.pos, range.end))
    .filter((comment) => comment.startsWith('/**'))
    .at(-1);
  if (!doc) return '';
  return doc
    .replace(/^\/\*\*|\*\/$/g, '')
    .split('\n')
    .map((line) => line.replace(/^\s*\* ?/, '').trim())
    .filter(Boolean)
    .join(' ');
}

/** `node` without `as const` / `satisfies …` wrappers. */
function unwrap(node: ts.Expression): ts.Expression {
  if (ts.isAsExpression(node) || ts.isSatisfiesExpression(node)) return unwrap(node.expression);
  return node;
}

/** Source text on one line, without the trailing comma a multi-line array carries. */
function oneLine(node: ts.Node, source: ts.SourceFile): string {
  return node
    .getText(source)
    .replace(/\[\s*\n\s*/g, '[')
    .replace(/,?\s*\n\s*\]/g, ']')
    .replace(/\s*\n\s*/g, ' ');
}

/** A table cell: code span (doubled backticks around a value that contains one), pipes escaped. */
const code = (value: string) =>
  (value.includes('`') ? `\`\` ${value} \`\`` : `\`${value}\``).replaceAll('|', '\\|');
const cell = (value: string) => value.replaceAll('|', '\\|');

/**
 * The rows of one object literal. A property whose object literal spans several lines in the
 * source (COPY's screens) becomes its own section; a one-line object stays one row.
 */
function collect(
  object: ts.ObjectLiteralExpression,
  prefix: string,
  ctx: { source: ts.SourceFile; text: string; locals: Map<string, ts.VariableDeclaration> },
  sections: Section[],
): Row[] {
  const rows: Row[] = [];
  for (const property of object.properties) {
    if (!ts.isPropertyAssignment(property) && !ts.isShorthandPropertyAssignment(property)) continue;
    const name = property.name.getText(ctx.source);
    let note = docOf(property, ctx.text);
    let value: ts.Expression = ts.isPropertyAssignment(property)
      ? property.initializer
      : property.name;
    // A shorthand or identifier naming a module-level const shows that const's value and doc.
    const local = ts.isIdentifier(value) ? ctx.locals.get(value.text) : undefined;
    if (local?.initializer) {
      note ||= docOf(local.parent.parent, ctx.text);
      value = local.initializer;
    }
    const inner = unwrap(value);
    const multiLine = inner.getText(ctx.source).includes('\n');
    if (ts.isObjectLiteralExpression(inner) && multiLine) {
      const title = `${prefix}${name}`;
      sections.push({ title, intro: note, rows: collect(inner, '', ctx, sections) });
      continue;
    }
    rows.push({ name: `${prefix}${name}`, value: oneLine(inner, ctx.source), note });
  }
  return rows;
}

/** The sections of one constants file: each `export const NAME = { … }`, then its sub-sections. */
function sectionsOf(file: string): Section[] {
  const text = readFileSync(new URL(file, SOURCE_DIR), 'utf8');
  const source = ts.createSourceFile(file, text, ts.ScriptTarget.Latest, true);
  const locals = new Map<string, ts.VariableDeclaration>();
  const sections: Section[] = [];
  for (const statement of source.statements) {
    if (!ts.isVariableStatement(statement)) continue;
    const exported = statement.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword);
    for (const declaration of statement.declarationList.declarations) {
      const name = declaration.name.getText(source);
      locals.set(name, declaration);
      const object = declaration.initializer && unwrap(declaration.initializer);
      if (!exported || !object || !ts.isObjectLiteralExpression(object)) continue;
      const nested: Section[] = [];
      const intro = `\`${file}\`. ${docOf(statement, text)}`.trim();
      const rows = collect(object, '', { source, text, locals }, nested);
      sections.push({ title: name, intro, rows });
      for (const section of nested)
        sections.push({ ...section, title: `${name}.${section.title}` });
    }
  }
  return sections;
}

function render(section: Section): string {
  const level = section.title.includes('.') ? '###' : '##';
  const lines = [`${level} ${section.title}`, ''];
  if (section.intro) lines.push(section.intro, '');
  if (section.rows.length > 0) lines.push('| Name | Value | Notes |', '|---|---|---|');
  for (const row of section.rows) {
    lines.push(`| ${code(row.name)} | ${code(row.value)} | ${cell(row.note)} |`);
  }
  return lines.join('\n').trimEnd();
}

// The barrel's `export * from './x.ts'` lines give the files and their order.
const barrel = readFileSync(new URL('index.ts', SOURCE_DIR), 'utf8');
const files = [...barrel.matchAll(/^export \* from '\.\/([\w-]+\.ts)';$/gm)].map(
  ([, file]) => file,
);
const markdown = `${HEADER}\n${files.flatMap(sectionsOf).map(render).join('\n\n')}\n`;

if (process.argv.includes('--check')) {
  const current = readFileSync(OUTPUT, 'utf8');
  if (current !== markdown) {
    console.error('docs/constants.md is stale: run `pnpm constants:docs` and commit the result.');
    process.exit(1);
  }
} else {
  writeFileSync(OUTPUT, markdown);
}
